// Avatares disponibles para el personaje.
export const AVATARS = [
  'domino-mask', 'carnival-mask', 'fox-head', 'wolf-head', 'imp-laugh', 'raven',
  'cat', 'owl', 'daemon-skull', 'hood', 'ninja-head', 'devil-mask',
];

// SVG de un ícono. Si `id` no es un ícono conocido (ej. un emoji de datos antiguos), se muestra como texto.
export function icon(id, cls = 'ico') {
  const body = ICONS[id];
  if (!body) return `<span class="${cls} ico-text">${String(id ?? '').replace(/[&<>"']/g, '')}</span>`;
  return `<svg class="${cls}" viewBox="0 0 512 512" aria-hidden="true">${body}</svg>`;
}
